const typography = {
  fontFamily: [
    "Inter",
    "-apple-system",
    "BlinkMacSystemFont",
    '"Segoe UI"',
    "Roboto",
    '"Helvetica Neue"',
    "Arial",
    "sans-serif",
  ].join(","),

  h1: {
    fontSize: "3.5rem",
    fontWeight: 800,
    lineHeight: 1.1,
    letterSpacing: "-0.03em",
  },

  h2: {
    fontSize: "3rem",
    fontWeight: 700,
    lineHeight: 1.15,
    letterSpacing: "-0.02em",
  },

  h3: {
    fontSize: "2.25rem",
    fontWeight: 700,
    lineHeight: 1.2,
  },

  h4: {
    fontSize: "1.75rem",
    fontWeight: 700,
    lineHeight: 1.25,
  },

  h5: {
    fontSize: "1.5rem",
    fontWeight: 700,
    lineHeight: 1.3,
  },

  h6: {
    fontSize: "1.25rem",
    fontWeight: 700,
    lineHeight: 1.35,
  },

  subtitle1: {
    fontSize: "1rem",
    fontWeight: 600,
  },

  subtitle2: {
    fontSize: "0.875rem",
    fontWeight: 600,
  },

  body1: {
    fontSize: "1rem",
    lineHeight: 1.7,
  },

  body2: {
    fontSize: "0.875rem",
    lineHeight: 1.6,
  },

  button: {
    textTransform: "none" as const,
    fontWeight: 700,
    fontSize: "1rem",
  },

  caption: {
    fontSize: "0.75rem",
  },

  overline: {
    fontSize: "0.75rem",
    fontWeight: 700,
    textTransform: "uppercase" as const,
    letterSpacing: "0.12em",
  },
};

export default typography;
